import sys
from collections import Counter

def main():
    input_data = sys.stdin.read().strip().split()
    idx = 0
    N = int(input_data[idx]); idx += 1

    dice = []
    for _ in range(N):
        K = int(input_data[idx]); idx += 1
        faces = input_data[idx:idx+K]
        idx += K
        cnt = Counter(faces)
        dice.append((K, cnt))

    best = 0.0
    for i in range(N):
        Ki, ci = dice[i]
        for j in range(i+1, N):
            Kj, cj = dice[j]
            common = 0
            if len(ci) < len(cj):
                for k, v in ci.items():
                    if k in cj:
                        common += v * cj[k]
            else:
                for k, v in cj.items():
                    if k in ci:
                        common += v * ci[k]
            prob = common / (Ki * Kj)
            if prob > best:
                best = prob

    print(f"{best:.15f}")

main()
