import sys
from collections import deque

def main():
    data = sys.stdin.read().split()
    N = int(data[0])
    grid = data[1:1+N]

    INF = 10**9
    dist = [[[INF]*N for _ in range(N)] for _ in range(3)]
    dq = deque()

    for i in range(N):
        dist[0][i][i] = 0
        dq.append((0, i, i))
        for j in range(N):
            if grid[i][j] != '-':
                if dist[1][i][j] > 1:
                    dist[1][i][j] = 1
                    dq.append((1, i, j))

    while dq:
        st, u, v = dq.popleft()
        d = dist[st][u][v]
        if st == 0:
            for a in range(N):
                if grid[a][u] == '-':
                    continue
                for b in range(N):
                    if grid[v][b] != '-' and grid[a][u] == grid[v][b]:
                        nd = d + 2
                        if dist[0][a][b] > nd:
                            dist[0][a][b] = nd
                            dq.append((0, a, b))
        else:
            # st == 1: u->v is pending matched pair, close it
            if u == v:
                if dist[0][u][v] > d:
                    dist[0][u][v] = d
                    dq.append((0, u, v))
            for a in range(N):
                if grid[a][u] == '-':
                    continue
                for b in range(N):
                    if grid[v][b] != '-' and grid[a][u] == grid[v][b]:
                        nd = d + 2
                        if dist[0][a][b] > nd:
                            dist[0][a][b] = nd
                            dq.append((0, a, b))

    out = []
    for i in range(N):
        row = []
        for j in range(N):
            best = min(dist[0][i][j], dist[1][i][j])
            row.append(best if best < INF else -1)
        out.append(' '.join(map(str, row)))
    sys.stdout.write('\n'.join(out) + '\n')

main()
