from typing import List

class Solution:
    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        mentions = [0] * numberOfUsers
        offline_until = [0] * numberOfUsers

        def sort_key(event):
            t = int(event[1])
            # OFFLINE before MESSAGE at same timestamp so status changes applied first
            priority = 0 if event[0] == "OFFLINE" else 1
            return (t, priority)

        for event in sorted(events, key=sort_key):
            typ, ts, val = event[0], int(event[1]), event[2]

            if typ == "OFFLINE":
                uid = int(val)
                offline_until[uid] = ts + 60
            else:
                if val == "ALL":
                    for i in range(numberOfUsers):
                        mentions[i] += 1
                elif val == "HERE":
                    for i in range(numberOfUsers):
                        if offline_until[i] <= ts:
                            mentions[i] += 1
                else:
                    for token in val.split():
                        uid = int(token[2:])
                        mentions[uid] += 1

        return mentions
