import sys

def solve():
    input = sys.stdin.readline
    N, M = map(int, input().split())
    segs = [tuple(map(int, input().split())) for _ in range(M)]

    # Precompute for Op1 greedy cover
    def min_op1_cover(target_l, target_r, available):
        """Minimum Op1 intervals from available to cover [target_l, target_r]"""
        if target_l > target_r:
            return 0, []
        sorted_ints = sorted([(l, r, idx) for idx, (l, r) in enumerate(available)])
        count = 0
        current = target_l
        used = []
        i = 0
        n = len(sorted_ints)

        while current <= target_r:
            best_r = current - 1
            best_idx = -1
            while i < n and sorted_ints[i][0] <= current:
                if sorted_ints[i][1] > best_r:
                    best_r = sorted_ints[i][1]
                    best_idx = sorted_ints[i][2]
                i += 1
            if best_r < current:
                return float('inf'), []
            count += 1
            used.append(best_idx)
            current = best_r + 1

        return count, used

    best_cost = float('inf')
    best_ops = None

    # Case 1: No Op2
    cost, used = min_op1_cover(1, N, segs)
    if cost < best_cost:
        best_cost = cost
        best_ops = [0] * M
        for idx in used:
            best_ops[idx] = 1

    # Case 2: One Op2
    for i in range(M):
        L, R = segs[i]
        # Op2 sets outside [L,R] to 1, need Op1 cover [L,R]
        available = [(segs[j][0], segs[j][1], j) for j in range(M) if j != i]
        cost, used = min_op1_cover(L, R, available)
        if cost < float('inf'):
            total = 1 + cost
            if total < best_cost:
                best_cost = total
                best_ops = [0] * M
                best_ops[i] = 2
                for idx in used:
                    best_ops[idx] = 1

    # Case 3: Two Op2 (take one with max L, one with min R)
    for i in range(M):
        for j in range(i+1, M):
            L1, R1 = segs[i]
            L2, R2 = segs[j]
            IL = max(L1, L2)
            IR = min(R1, R2)
            if IL <= IR:
                # Intersection is [IL, IR]
                available = [(segs[k][0], segs[k][1], k) for k in range(M) if k != i and k != j]
                cost, used = min_op1_cover(IL, IR, available)
                if cost < float('inf'):
                    total = 2 + cost
                    if total < best_cost:
                        best_cost = total
                        best_ops = [0] * M
                        best_ops[i] = 2
                        best_ops[j] = 2
                        for idx in used:
                            best_ops[idx] = 1
            else:
                # Empty intersection, cost 2
                if 2 < best_cost:
                    best_cost = 2
                    best_ops = [0] * M
                    best_ops[i] = 2
                    best_ops[j] = 2

    if best_cost == float('inf'):
        print(-1)
    else:
        print(best_cost)
        print(' '.join(map(str, best_ops)))

if __name__ == "__main__":
    solve()
