from typing import List

class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        n = len(words)
        if n - 1 < k:
            return [0] * n

        trie = [{}]
        cnt = [0]
        depth = [0]

        for w in words:
            node = 0
            for ch in w:
                if ch not in trie[node]:
                    trie[node][ch] = len(trie)
                    trie.append({})
                    cnt.append(0)
                    depth.append(depth[node] + 1)
                node = trie[node][ch]
                cnt[node] += 1

        m = len(trie)
        maxdepth = [0] * m

        for node in range(m - 1, -1, -1):
            if cnt[node] >= k:
                maxdepth[node] = depth[node]
            else:
                maxdepth[node] = 0
            for ch, child in trie[node].items():
                if maxdepth[child] > maxdepth[node]:
                    maxdepth[node] = maxdepth[child]

        top1 = [(-1, -1)] * m
        top2 = [(-1, -1)] * m

        for node in range(m):
            for ch, child in trie[node].items():
                val = maxdepth[child]
                if val > top1[node][0]:
                    top2[node] = top1[node]
                    top1[node] = (val, child)
                elif val > top2[node][0]:
                    top2[node] = (val, child)

        answers = []
        for i in range(n):
            w = words[i]
            node = 0
            best = 0

            for ch in w:
                child = trie[node][ch]
                if top1[node][1] == child:
                    alt = top2[node][0]
                else:
                    alt = top1[node][0]
                if alt > best:
                    best = alt
                if cnt[child] - 1 >= k:
                    if depth[child] > best:
                        best = depth[child]
                node = child

            if top1[node][0] > best:
                best = top1[node][0]

            answers.append(best)

        return answers
