class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n, m = len(str1), len(str2)
        L = n + m - 1
        res = [''] * L
        fixed = [False] * L

        # Apply all 'T' constraints
        for i in range(n):
            if str1[i] == 'T':
                for j in range(m):
                    pos = i + j
                    if fixed[pos]:
                        if res[pos] != str2[j]:
                            return ""
                    else:
                        res[pos] = str2[j]
                        fixed[pos] = True

        # Fill unfixed positions with 'a' initially
        for i in range(L):
            if not fixed[i]:
                res[i] = 'a'

        # Check 'F' constraints, try to fix by raising characters greedily from right to left
        for i in range(n - 1, -1, -1):
            if str1[i] == 'F':
                # Check if substring matches str2
                match = True
                for j in range(m):
                    if res[i + j] != str2[j]:
                        match = False
                        break
                if match:
                    # Need to break the match: find rightmost position in [i, i+m-1] that is not fixed
                    # and can be incremented
                    found = False
                    for j in range(m - 1, -1, -1):
                        pos = i + j
                        if not fixed[pos]:
                            # Try to increase res[pos] to something > str2[j]
                            c = res[pos]
                            if c < str2[j]:
                                # Any char > c works but we want smallest to break match; but must differ from str2[j]
                                # The smallest char > c that is != str2[j] if c+1 == str2[j] then go to next
                                nc = chr(ord(c) + 1)
                                if nc == str2[j]:
                                    if ord(nc) + 1 <= ord('z'):
                                        nc = chr(ord(nc) + 1)
                                    else:
                                        continue
                                res[pos] = nc
                                found = True
                                break
                            else:
                                # c > str2[j], already doesn't match at this pos? Wait match was true so c == str2[j]
                                # Actually if match true, res[pos] == str2[j], so c == str2[j]. So this branch is c >= str2[j]
                                # c == str2[j], to differ: increase c
                                if ord(c) + 1 <= ord('z'):
                                    res[pos] = chr(ord(c) + 1)
                                    found = True
                                    break
                                else:
                                    continue
                    if not found:
                        return ""

        return ''.join(res)
