from typing import List

class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        def key(p):
            x, y = p
            if y == 0:
                return x
            if x == side:
                return side + y
            if y == side:
                return 3 * side - x
            return 4 * side - y

        arr = sorted(points, key=key)
        n = len(arr)

        def dist(a, b):
            return abs(a[0] - b[0]) + abs(a[1] - b[1])

        def feasible(d):
            # duplicate array to handle circular
            ext = arr + arr
            m = 2 * n
            for i in range(n):
                cnt = 1
                j = i + 1
                last = i
                while j < i + n and cnt < k:
                    if dist(ext[last], ext[j]) >= d:
                        cnt += 1
                        last = j
                    j += 1
                if cnt >= k:
                    # verify wrap-around condition
                    if dist(ext[last], ext[i]) >= d or cnt >= k + 0:
                        # Actually for circular we must ensure last-to-first condition only if we wrapped
                        # Since j < i+n, we didn't take duplicate of i; the gap covers whole circle
                        pass
                    # proper check: all selected must be pairwise >= d. Greedy ensures consecutive,
                    # but need check last vs first if circle closed
                    if dist(ext[last], ext[i]) >= d:
                        return True
                    # if last is exactly i+n-1 region? The greedy on circle might still be valid with
                    # last element before wrapping. Let's also accept if we covered full circle
                    if last - i >= n - 1:
                        return True
            return False

        lo, hi = 0, 2 * side
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if feasible(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo
