import sys
from collections import defaultdict

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    N = int(data[0])
    P = int(data[1])
    MOD = P

    max_edges = N*(N-1)//2
    half = N//2

    fact = [1]*(N+1)
    for i in range(1,N+1):
        fact[i] = fact[i-1]*i % MOD
    inv_fact = [1]*(N+1)
    inv_fact[N] = pow(fact[N], MOD-2, MOD)
    for i in range(N,0,-1):
        inv_fact[i-1] = inv_fact[i]*i % MOD

    max_fact = max_edges
    fact_big = [1]*(max_fact+1)
    for i in range(1, max_fact+1):
        fact_big[i] = fact_big[i-1]*i % MOD
    inv_fact_big = [1]*(max_fact+1)
    if max_fact >= 0:
        inv_fact_big[max_fact] = pow(fact_big[max_fact], MOD-2, MOD)
    for i in range(max_fact,0,-1):
        inv_fact_big[i-1] = inv_fact_big[i]*i % MOD

    def binom(n,k):
        if k<0 or k>n: return 0
        return fact_big[n]*inv_fact_big[k]%MOD*inv_fact_big[n-k]%MOD

    # Precompute (1+x)^k
    poly_1x = []
    for k in range(max_edges+1):
        arr = [0]*(max_edges+1)
        for j in range(min(k, max_edges)+1):
            arr[j] = binom(k,j)
        poly_1x.append(arr)

    # Precompute f(a,b) for a,b up to N
    f_poly = {}
    for a in range(N+1):
        for b in range(N+1):
            deg = a*b
            if deg > max_edges: continue
            poly = [0]*(max_edges+1)
            for t in range(b+1):
                sign = 1 if t%2==0 else -1
                coef = binom(b,t) * sign % MOD
                powv = a*(b-t)
                if powv > max_edges: continue
                base = poly_1x[powv]
                for j in range(min(powv, max_edges)+1):
                    if base[j]:
                        poly[j] = (poly[j] + coef * base[j]) % MOD
            f_poly[(a,b)] = poly

    # DP
    # dp: key -> poly
    # initial: used=1, even=1, prev=1, parity=1 (next layer odd)
    dp = defaultdict(lambda: [0]*(max_edges+1))
    dp[(1, 1, 1, 1)][0] = 1

    # iterate exactly N times (max layers)
    for _ in range(N):
        new_dp = defaultdict(lambda: [0]*(max_edges+1))
        for (used, even, prev, parity), poly in dp.items():
            if used == N:
                # carry forward
                key = (used, even, prev, parity)
                for i in range(max_edges+1):
                    if poly[i]:
                        new_dp[key][i] = (new_dp[key][i] + poly[i]) % MOD
                continue
            max_s = N - used
            for s in range(1, max_s+1):
                new_used = used + s
                new_even = even + (s if parity==0 else 0)
                new_odd = new_used - new_even
                if new_even > half or new_odd > half:
                    continue
                new_parity = 1 - parity
                factor = inv_fact[s]
                c2 = s*(s-1)//2
                if c2 > max_edges: continue
                poly_within = poly_1x[c2]
                poly_bip = f_poly.get((prev, s), None)
                if poly_bip is None: continue
                # convolve poly * poly_within
                temp = [0]*(max_edges+1)
                for i in range(max_edges+1):
                    if poly[i]==0: continue
                    pi = poly[i]
                    upto = min(c2, max_edges-i)
                    for j in range(upto+1):
                        if poly_within[j]:
                            temp[i+j] = (temp[i+j] + pi * poly_within[j]) % MOD
                # convolve temp * poly_bip
                res = [0]*(max_edges+1)
                deg_bip = prev*s
                for i in range(max_edges+1):
                    if temp[i]==0: continue
                    ti = temp[i]
                    upto = min(deg_bip, max_edges-i)
                    for j in range(upto+1):
                        if poly_bip[j]:
                            res[i+j] = (res[i+j] + ti * poly_bip[j]) % MOD
                # multiply by factor
                for i in range(max_edges+1):
                    if res[i]:
                        res[i] = res[i] * factor % MOD
                key = (new_used, new_even, s, new_parity)
                for i in range(max_edges+1):
                    if res[i]:
                        new_dp[key][i] = (new_dp[key][i] + res[i]) % MOD
        dp = new_dp
        if not dp:
            break

    ans = [0]*(max_edges+1)
    for (used, even, prev, parity), poly in dp.items():
        if used == N and even == half:
            mult = fact[N-1]
            for i in range(max_edges+1):
                if poly[i]:
                    ans[i] = (ans[i] + poly[i] * mult) % MOD

    out = []
    for M in range(N-1, max_edges+1):
        out.append(str(ans[M] % MOD))
    print(' '.join(out))

if __name__ == '__main__':
    solve()
