```python
class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n, m = len(str1), len(str2)
        L = n + m - 1
        word = [None] * L
        fixed = [False] * L

        # Apply all 'T' constraints
        for i in range(n):
            if str1[i] == 'T':
                for k in range(m):
                    idx = i + k
                    if word[idx] is None:
                        word[idx] = str2[k]
                        fixed[idx] = True
                    elif word[idx] != str2[k]:
                        return ""

        # Fill unconstrained positions with smallest letter 'a'
        for i in range(L):
            if word[i] is None:
                word[i] = 'a'

        # Fix 'F' violations, iterate until stable
        changed = True
        while changed:
            changed = False
            for i in range(n):
                if str1[i] == 'F':
                    if ''.join(word[i:i + m]) == str2:
                        fixed_any = False
                        # First try to make it smaller by setting a free pos to 'a'
                        for p in range(i + m - 1, i - 1, -1):
                            if not fixed[p] and str2[p - i] > 'a':
                                word[p] = 'a'
                                changed = True
                                fixed_any = True
                                break
                        if fixed_any:
                            continue
                        # Otherwise, increase a free pos minimally, from the right
                        for p in range(i + m - 1, i - 1, -1):
                            if not fixed[p]:
                                if str2[p - i] < 'z':
                                    word[p] = chr(ord(str2[p - i]) + 1)
                                    changed = True
                                    fixed_any = True
                                    break
                        if not fixed_any:
                            return ""
        return ''.join(word)
