    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    it = iter(data)
    n = next(it)

    dice = []
    for _ in range(n):
        k = next(it)
        cnt = {}
        for _ in range(k):
            a = next(it)
            cnt[a] = cnt.get(a, 0) + 1
        dice.append((k, cnt))

    ans = 0.0

    for i in range(n):
        ki, ci = dice[i]
        for j in range(i + 1, n):
            kj, cj = dice[j]

            if len(ci) > len(cj):
                small, big = cj, ci
            else:
                small, big = ci, cj

            common = 0
            for value, count_small in small.items():
                count_big = big.get(value)
                if count_big is not None:
                    common += count_small * count_big

            prob = common / (ki * kj)
            if prob > ans:
                ans = prob

    print(f"{ans:.15f}")


if __name__ == "__main__":
    main()
