import sys

def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return

    it = iter(data)
    N = int(next(it))
    M = int(next(it))

    adj = [[] for _ in range(N)]
    for _ in range(M):
        u = int(next(it)) - 1
        v = int(next(it)) - 1
        w = int(next(it))
        adj[u].append((v, w))
        adj[v].append((u, w))

    target = N - 1
    ans = 1 << 60

    def dfs(v, used, value):
        nonlocal ans
        if v == target:
            if value < ans:
                ans = value
            return

        for to, w in adj[v]:
            if not (used >> to) & 1:
                dfs(to, used | (1 << to), value ^ w)

