from typing import List

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])

        dr = [1, 1, -1, -1]
        dc = [1, -1, -1, 1]

        expected_vals = [1, 2, 0]

        run2 = [[[[0]*m for _ in range(n)] for _ in range(3)] for _ in range(4)]

        for d in range(4):
            if d == 0:
                i_range = range(n-1, -1, -1)
                j_range = range(m-1, -1, -1)
            elif d == 1:
                i_range = range(n-1, -1, -1)
                j_range = range(m)
            elif d == 2:
                i_range = range(n)
                j_range = range(m)
            else:
                i_range = range(n)
                j_range = range(m-1, -1, -1)

            for i in i_range:
                for j in j_range:
                    for p in range(3):
                        if grid[i][j] != expected_vals[p]:
                            run2[d][p][i][j] = 0
                        else:
                            ni, nj = i + dr[d], j + dc[d]
                            if 0 <= ni < n and 0 <= nj < m:
                                if p == 0:
                                    np_ = 1
                                elif p == 1:
                                    np_ = 2
                                else:
                                    np_ = 1
                                run2[d][p][i][j] = 1 + run2[d][np_][ni][nj]
                            else:
                                run2[d][p][i][j] = 1

        ans = 0

        for d in range(4):
            for i in range(n):
                for j in range(m):
                    if grid[i][j] == 1:
                        if run2[d][0][i][j] > ans:
                            ans = run2[d][0][i][j]

        turnval = [[[[0]*m for _ in range(n)] for _ in range(3)] for _ in range(4)]
        for d2 in range(4):
            for p in range(3):
                for x in range(n):
                    for y in range(m):
                        nx, ny = x + dr[d2], y + dc[d2]
                        if 0 <= nx < n and 0 <= ny < m:
                            turnval[d2][p][x][y] = run2[d2][p][nx][ny]

        for i in range(n):
            for j in range(m):
                if grid[i][j] != 1:
                    continue
                for d1 in range(4):
                    d2 = (d1 + 1) % 4
                    x, y = i, j
                    L1 = 1
                    while 0 <= x < n and 0 <= y < m:
                        if L1 == 1:
                            if grid[x][y] != 1:
                                break
                        elif L1 % 2 == 0:
                            if grid[x][y] != 2:
                                break
                        else:
                            if grid[x][y] != 0:
                                break
                        p = 1 if (L1 % 2 == 1) else 2
                        cand = L1 + turnval[d2][p][x][y]
                        if cand > ans:
                            ans = cand
                        x += dr[d1]
                        y += dc[d1]
                        L1 += 1

        return ans
