import sys

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    it = iter(data)
    N = next(it)
    X = next(it)

    U = [0] * N
    D = [0] * N
    total = 0
    min_sum = 10**30

    for i in range(N):
        u = next(it)
        d = next(it)
        U[i] = u
        D[i] = d
        total += u + d
        s = u + d
        if s < min_sum:
            min_sum = s

    def feasible(H):
        lo = H - D[0]
        if lo < 0:
            lo = 0
        hi = U[0]
        if H < hi:
            hi = H
        if lo > hi:
            return False

        for i in range(1, N):
            L = H - D[i]
            if L < 0:
                L = 0
            R = U[i]
            if H < R:
                R = H

            nlo = lo - X
            if L > nlo:
                nlo = L

            nhi = hi + X
            if R < nhi:
                nhi = R

            if nlo > nhi:
                return False

            lo, hi = nlo, nhi

        return True

    low = 0
    high = min_sum

    while low < high:
        mid = (low + high + 1) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid - 1

    answer = total - N * low
    print(answer)


if __name__ == "__main__":
    solve()
