from typing import List

class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)

        def feasible(target: int) -> bool:
            moves = 0
            for i, v in enumerate(points):
                if i == 0:
                    need = (target + v - 1) // v
                    moves = need
                else:
                    if i == n - 1:
                        need = (target + v - 1) // v
                        moves += need
                    else:
                        need = (target + v - 1) // v
                        if need == 0:
                            moves += 0
                        else:
                            cost = need * 2 - 1
                            if i == 0:
                                cost -= 1
                            moves += cost
                if moves > m:
                    return False
            if moves <= m:
                return True
            return False

        lo, hi = 0, min(points) * (m // 2 + 1)
        hi = min(points) * (m + 1)
        res = 0
        while lo <= hi:
            mid = (lo + hi) // 2
            if feasible(mid):
                res = mid
                lo = mid + 1
            else:
                hi = mid - 1
        return res
