            y = A[i + 1]
            if x == y:
                continue
            if x > y:
                x, y = y, x
            key = (x, y)
            edge = (i, i + 1)
            if key in groups:
                groups[key].append(edge)
            else:
                groups[key] = [edge]

        ans = 0
        for (x, y), edges in groups.items():
            if adjacent[x] or adjacent[y]:
