import sys
from collections import deque

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    N = int(data[0])
    grid = data[1:1 + N]

    out_bits = [[0] * 26 for _ in range(N)]
    in_bits = [[0] * 26 for _ in range(N)]

    for u in range(N):
        row = grid[u]
        for v, ch in enumerate(row):
            if ch != '-':
                c = ord(ch) - ord('a')
                out_bits[u][c] |= 1 << v
                in_bits[v][c] |= 1 << u

    ans = [[-1] * N for _ in range(N)]
    visited_rows = [0] * N
    q = deque()

    for i in range(N):
        ans[i][i] = 0
        visited_rows[i] |= 1 << i
        q.append((i, i))

    for u in range(N):
        row = grid[u]
        for v, ch in enumerate(row):
            if ch != '-' and ans[u][v] == -1:
                ans[u][v] = 1
                visited_rows[u] |= 1 << v
                q.append((u, v))

    while q:
        a, b = q.popleft()
        d = ans[a][b]

        for c in range(26):
            S = in_bits[a][c]
            if S == 0:
                continue
            T = out_bits[b][c]
            if T == 0:
                continue

            ss = S
            while ss:
                lsb = ss & -ss
                s = lsb.bit_length() - 1
                new = T & ~visited_rows[s]

                while new:
                    lsb2 = new & -new
                    t = lsb2.bit_length() - 1
                    ans[s][t] = d + 2
                    visited_rows[s] |= lsb2
                    q.append((s, t))
                    new -= lsb2

                ss -= lsb

    out_lines = []
    for i in range(N):
        out_lines.append(' '.join(str(ans[i][j]) for j in range(N)))
    sys.stdout.write('\n'.join(out_lines))

if __name__ == "__main__":
    main()
