class Solution:
    def longestPalindromicSubsequence(self, s: str, k: int) -> int:
        n = len(s)

        def pair_cost(a: str, b: str) -> int:
            d = abs(ord(a) - ord(b))
            return min(d, 26 - d)

        prev1 = None
        prev2 = None

        for length in range(1, n + 1):
            count = n - length + 1
            curr = [[0] * (k + 1) for _ in range(count)]

            if length == 1:
                for i in range(count):
                    curr[i] = [1] * (k + 1)
            else:
                for i in range(count):
                    j = i + length - 1
                    arr = curr[i]
                    left = prev1[i]
                    right = prev1[i + 1]
                    cost = pair_cost(s[i], s[j])

                    if length == 2:
                        for b in range(k + 1):
                            best = left[b] if left[b] > right[b] else right[b]
                            if b >= cost and 2 > best:
                                best = 2
                            arr[b] = best
                    else:
                        middle = prev2[i + 1]
                        for b in range(k + 1):
                            best = left[b] if left[b] > right[b] else right[b]
                            if b >= cost:
                                cand = middle[b - cost] + 2
                                if cand > best:
                                    best = cand
                            arr[b] = best

            prev2, prev1 = prev1, curr

        return prev1[0][k]
