import sys
from collections import deque

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    N = int(data[0])
    rows = data[1:1 + N]

    pred = [[[] for _ in range(N)] for _ in range(26)]
    succ = [[[] for _ in range(N)] for _ in range(26)]

    for i in range(N):
        for j, ch in enumerate(rows[i]):
            if ch != '-':
                c = ord(ch) - ord('a')
                pred[c][j].append(i)
                succ[c][i].append(j)

    dist = [[-1] * N for _ in range(N)]
    q = deque()
    total = N * N
    count = 0

    for i in range(N):
        dist[i][i] = 0
        q.append((i, i))
        count += 1

    for i in range(N):
        for j, ch in enumerate(rows[i]):
            if ch != '-' and i != j:
                if dist[i][j] == -1:
                    dist[i][j] = 1
                    q.append((i, j))
                    count += 1

    while q and count < total:
        a, b = q.popleft()
        nd = dist[a][b] + 2

        for c in range(26):
            pl = pred[c][a]
            if not pl:
                continue
            sl = succ[c][b]
            if not sl:
                continue

            for s in pl:
                ds = dist[s]
                for t in sl:
                    if ds[t] == -1:
                        ds[t] = nd
                        q.append((s, t))
                        count += 1
                        if count == total:
                            break
                if count == total:
                    break
            if count == total:
                break

    out = []
    for i in range(N):
        out.append(' '.join(str(dist[i][j]) for j in range(N)))
    sys.stdout.write('\n'.join(out))

if __name__ == "__main__":
