from typing import List

class Solution:
    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        events.sort(key=lambda x: int(x[1]))
        mentions = [0] * numberOfUsers
        offline_until = [0] * numberOfUsers
        n = len(events)
        i = 0

        while i < n:
            t = int(events[i][1])

            # Process automatic online for users whose offline period ended
            for u in range(numberOfUsers):
                if offline_until[u] != 0 and offline_until[u] <= t:
                    offline_until[u] = 0

            # Process all OFFLINE events at time t
            k = i
            while k < n and int(events[k][1]) == t:
                if events[k][0] == "OFFLINE":
                    uid = int(events[k][2])
                    offline_until[uid] = t + 60
                k += 1

            # Process all MESSAGE events at time t
            k = i
            while k < n and int(events[k][1]) == t:
                if events[k][0] == "MESSAGE":
                    content = events[k][2]
                    if content == "ALL":
                        for u in range(numberOfUsers):
                            mentions[u] += 1
                    elif content == "HERE":
                        for u in range(numberOfUsers):
                            if offline_until[u] == 0:
                                mentions[u] += 1
                    else:
                        for token in content.split():
                            if token.startswith("id"):
                                uid = int(token[2:])
                                mentions[uid] += 1
                k += 1

            i = k

        return mentions
