class Solution:
    def countSubstrings(self, s: str) -> int:
        counts = [None] * 10
        for d in range(1, 10):
            counts[d] = [0] * d

        ans = 0

        for ch in s:
            c = ord(ch) - ord('0')

            for d in range(1, 10):
                old = counts[d]
                if d == 1:
                    old[0] += 1
                else:
                    new = [0] * d
                    for r, val in enumerate(old):
                        if val:
                            new[(r * 10 + c) % d] += val
                    new[c % d] += 1
                    counts[d] = new

            if c != 0:
                ans += counts[c][0]

        return ans
