from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        m = len(conflictingPairs)
        by_y = [[] for _ in range(n + 1)]

        for idx, (a, b) in enumerate(conflictingPairs):
            x, y = (a, b) if a < b else (b, a)
            by_y[y].append((x, idx))

        base = 0
        benefit = [0] * m

        max_x = 0
        second_x = 0
        count_max = 0
        top_id = -1

        for r in range(1, n + 1):
            for x, idx in by_y[r]:
                if x > max_x:
                    second_x = max_x
                    max_x = x
                    count_max = 1
                    top_id = idx
                elif x == max_x:
                    count_max += 1
                else:
                    if x > second_x:
                        second_x = x

            base += r - max_x

            if max_x > 0 and count_max == 1:
                benefit[top_id] += max_x - second_x

        return base + max(benefit)
