class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)
        L = n + m - 1

        fixed = [-1] * L

        for i, ch in enumerate(str1):
            if ch == 'T':
                for j, c in enumerate(str2):
                    pos = i + j
                    val = ord(c) - 97
                    if fixed[pos] != -1 and fixed[pos] != val:
                        return ""
                    fixed[pos] = val

        pi = [0] * m
        for i in range(1, m):
            j = pi[i - 1]
            while j > 0 and str2[i] != str2[j]:
                j = pi[j - 1]
            if str2[i] == str2[j]:
                j += 1
            pi[i] = j

        p_ord = [ord(c) - 97 for c in str2]
        trans = [[0] * 26 for _ in range(m + 1)]

        for s in range(m + 1):
            for c in range(26):
                t = s
                if t == m:
                    t = pi[m - 1]

                while t > 0 and p_ord[t] != c:
                    t = pi[t - 1]

                if p_ord[t] == c:
                    t += 1

                trans[s][c] = t

        reach = [0] * (m + 1)
        for s in range(m + 1):
            mask = 0
            for c in range(26):
                mask |= 1 << trans[s][c]
            reach[s] = mask

        possible_at = [0] * (L + 1)
        possible_next = (1 << (m + 1)) - 1
        possible_at[L] = possible_next

        for p in range(L - 1, -1, -1):
            start = p - m + 1
            forbidden = (0 <= start < n and str1[start] == 'F')
            mask = 0
            fc = fixed[p]

            if fc != -1:
                c = fc
                for s in range(m + 1):
                    ns = trans[s][c]
                    if forbidden and ns == m:
                        continue
                    if possible_next & (1 << ns):
                        mask |= 1 << s
            else:
                if forbidden:
                    allowed_next = possible_next & ~(1 << m)
                    if allowed_next:
                        for s in range(m + 1):
                            if reach[s] & allowed_next:
                                mask |= 1 << s
                else:
                    for s in range(m + 1):
                        if reach[s] & possible_next:
                            mask |= 1 << s

            possible_at[p] = mask
            possible_next = mask

        if not (possible_at[0] & 1):
            return ""

        state = 0
        res = []

        for p in range(L):
            start = p - m + 1
            forbidden = (0 <= start < n and str1[start] == 'F')
            fc = fixed[p]
            next_possible = possible_at[p + 1]
            chosen = -1
            ns = 0

            if fc != -1:
                c = fc
                ns = trans[state][c]
                if not (forbidden and ns == m) and (next_possible & (1 << ns)):
                    chosen = c
            else:
                for c in range(26):
                    ns = trans[state][c]
                    if forbidden and ns == m:
                        continue
                    if next_possible & (1 << ns):
                        chosen = c
                        break

            if chosen == -1:
                return ""

            res.append(chr(chosen + 97))
            state = ns

        return ''.join(res)
