import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    N = int(data[0])
    P = int(data[1])

    E = N // 2
    maxE = N * (N - 1) // 2
    MAX = max(N, maxE)

    comb = [[0] * (MAX + 1) for _ in range(MAX + 1)]
    for i in range(MAX + 1):
        comb[i][0] = 1
        comb[i][i] = 1
        for j in range(1, i):
            comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % P

    C2 = [n * (n - 1) // 2 for n in range(N + 1)]

    term_shifts = [[None] * (N + 1) for _ in range(N + 1)]
    term_coeffs = [[None] * (N + 1) for _ in range(N + 1)]

    for a in range(1, N + 1):
        for b in range(1, N + 1):
            shifts = []
            coeffs = []
            c = C2[b]
            for j in range(b + 1):
                coeff = comb[b][j]
                if (b - j) & 1:
                    coeff = (-coeff) % P
                if coeff:
                    shifts.append(a * j + c)
                    coeffs.append(coeff)
            term_shifts[a][b] = shifts
            term_coeffs[a][b] = coeffs

    dp = [[[[None] * (E + 1) for _ in range(2)] for _ in range(N + 1)] for _ in range(N + 1)]
    dp[1][1][0][1] = [1]

    for n in range(1, N):
        for a in range(1, n + 1):
            for p in range(2):
                for e in range(E + 1):
                    poly = dp[n][a][p][e]
                    if poly is not None:
                        for i, v in enumerate(poly):
                            if v >= P or v < 0:
                                poly[i] = v % P

        rem_max = N - n
        for a in range(1, n + 1):
            for p in range(2):
                for e in range(E + 1):
                    poly = dp[n][a][p][e]
                    if poly is None:
                        continue

                    for b in range(1, rem_max + 1):
                        n2 = n + b
                        p2 = 1 - p

                        if p == 1:
                            e2 = e + b
                            if e2 > E:
                                continue
                        else:
                            e2 = e

                        dest = dp[n2][b][p2][e2]
                        if dest is None:
                            dest = [0] * (C2[n2] + 1)
                            dp[n2][b][p2][e2] = dest

                        scale = comb[N - n][b]
                        shifts = term_shifts[a][b]
                        coeffs = term_coeffs[a][b]

                        for k in range(len(shifts)):
                            cs = coeffs[k] * scale % P
                            if cs == 0:
                                continue
                            sh = shifts[k]
                            for i, val in enumerate(poly):
                                if val:
                                    dest[i + sh] += val * cs

    sum_poly = [0] * (maxE + 1)
    for a in range(1, N + 1):
        for p in range(2):
            poly = dp[N][a][p][E]
            if poly is not None:
                for i, v in enumerate(poly):
                    if v:
                        sum_poly[i] = (sum_poly[i] + v) % P

    ans = []
    for M in range(N - 1, maxE + 1):
        s = 0
        for tdeg in range(M, maxE + 1):
            c = sum_poly[tdeg]
            if c:
                s = (s + c * comb[tdeg][M]) % P
        ans.append(str(s))

    sys.stdout.write(" ".join(ans))


if __name__ == "__main__":
    solve()
