from typing import List

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n = len(grid)
        m = len(grid[0])
        N = n * m

        vals = [0] * N
        for r in range(n):
            base = r * m
            row = grid[r]
            for c in range(m):
                vals[base + c] = row[c]

        # clockwise order
        dirs = [(1, 1), (1, -1), (-1, -1), (-1, 1)]
        next_val = [2, 2, 0]  # 0 -> 2, 1 -> 2, 2 -> 0

        ans = 0

        for d in range(4):
            dr, dc = dirs[d]

            # end[idx] = longest valid segment ending at idx along direction d
            end = [0] * N

            if dr == 1:
                r_range = range(n)
            else:
                r_range = range(n - 1, -1, -1)

            if dc == 1:
                c_range = range(m)
            else:
                c_range = range(m - 1, -1, -1)

            for r in r_range:
                base = r * m
                pr = r - dr
                for c in c_range:
                    idx = base + c
                    val = vals[idx]

                    if val == 1:
                        end[idx] = 1
                    else:
                        pc = c - dc
                        if 0 <= pr < n and 0 <= pc < m:
                            plen = end[pr * m + pc]
                            if plen > 0:
                                expected = 2 if (plen & 1) else 0
                                if val == expected:
                                    end[idx] = plen + 1

            # after-turn direction
            da = (d + 1) & 3
            dr2, dc2 = dirs[da]

            # f0[idx]: longest valid segment starting at idx along da, expecting 0
            # f2[idx]: longest valid segment starting at idx along da, expecting 2
            f0 = [0] * N
            f2 = [0] * N

            if dr2 == 1:
                r_range2 = range(n - 1, -1, -1)
            else:
                r_range2 = range(n)

            if dc2 == 1:
                c_range2 = range(m - 1, -1, -1)
            else:
                c_range2 = range(m)

            for r in r_range2:
                base = r * m
                sr = r + dr2
                for c in c_range2:
                    idx = base + c
                    val = vals[idx]
                    sc = c + dc2

                    if 0 <= sr < n and 0 <= sc < m:
                        sidx = sr * m + sc
                        if val == 0:
                            f0[idx] = 1 + f2[sidx]
                        if val == 2:
                            f2[idx] = 1 + f0[sidx]
                    else:
                        if val == 0:
                            f0[idx] = 1
                        if val == 2:
                            f2[idx] = 1

            # combine before-turn segment with after-turn segment
            for r in range(n):
                base = r * m
                for c in range(m):
                    idx = base + c
                    L = end[idx]
                    if L == 0:
                        continue

                    e = vals[idx]
                    ne = next_val[e]

                    ur = r + dr2
                    uc = c + dc2

                    if 0 <= ur < n and 0 <= uc < m:
                        uidx = ur * m + uc
                        if ne == 0:
                            add = f0[uidx]
                        else:
                            add = f2[uidx]
                    else:
                        add = 0

                    total = L + add
                    if total > ans:
                        ans = total

        return ans
