import sys
from collections import defaultdict

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    it = iter(data)
    n = next(it)

    k = [0] * n
    value_to_dice = defaultdict(list)

    for i in range(n):
        ki = next(it)
        k[i] = ki

        freq = {}
        for _ in range(ki):
            a = next(it)
            freq[a] = freq.get(a, 0) + 1

        for a, c in freq.items():
            value_to_dice[a].append((i, c))

    score = [[0] * n for _ in range(n)]

    for lst in value_to_dice.values():
        m = len(lst)
        for p in range(m):
            i, ci = lst[p]
            row_i = score[i]
            for q in range(p + 1, m):
                j, cj = lst[q]
                prod = ci * cj
                row_i[j] += prod
                score[j][i] += prod

    ans = 0.0

    for i in range(n):
        ki = k[i]
        row_i = score[i]
        for j in range(i + 1, n):
            prob = row_i[j] / (ki * k[j])
            if prob > ans:
                ans = prob

    sys.stdout.write(f"{ans:.15f}\n")

