from typing import List

class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        S = side
        C = 4 * S

        pos = []
        for x, y in points:
            if y == 0:
                t = x
            elif x == S:
                t = S + y
            elif y == S:
                t = 3 * S - x
            else:
                t = 4 * S - y
            pos.append(t)

        pos.sort()
        n = len(pos)

        def can(D: int) -> bool:
            if D == 0:
                return True

            ext = pos + [v + C for v in pos]
            m = 2 * n
            nxt = [m] * m

            p = 0
            for i in range(m):
                if p < i + 1:
                    p = i + 1
                target = ext[i] + D
                while p < m and ext[p] < target:
                    p += 1
                nxt[i] = p

            for start in range(n):
                cur = start
                cnt = 1
                limit = start + n

                while cnt < k:
                    nxt_idx = nxt[cur]
                    if nxt_idx >= limit:
                        break
                    cur = nxt_idx
                    cnt += 1

                if cnt >= k:
                    return True

            return False

        lo, hi = 0, S
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if can(mid):
                lo = mid
            else:
                hi = mid - 1

        return lo
