    dp_even = NEG

    for i, x in enumerate(a, start=1):
        if i & 1:
            cand = x
            if dp_even != NEG:
                cand = max(cand, dp_even + x)
            if cand > dp_odd:
                dp_odd = cand
        else:
            if dp_odd != NEG:
                cand = dp_odd + x
                if cand > dp_even:
                    dp_even = cand

    if n & 1:
        ans = dp_odd
    else:
        ans = max(0, dp_even) if dp_even != NEG else 0

    print(ans)

