    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)
        L = n + m - 1
        ans = ['?'] * L

        # Apply all 'T' constraints first
        for i in range(n):
            if str1[i] == 'T':
                for j in range(m):
                    pos = i + j
                    if ans[pos] != '?' and ans[pos] != str2[j]:
                        return ""
                    ans[pos] = str2[j]

        # Process 'F' constraints left to right
        for i in range(n):
            if str1[i] == 'F':
                unsafe = True
                for j in range(m):
                    pos = i + j
                    if ans[pos] == '?':
                        if str2[j] != 'a':
                            unsafe = False
                            break
                    else:
                        if ans[pos] != str2[j]:
                            unsafe = False
                            break

                if unsafe:
                    changed = False
                    for j in range(m - 1, -1, -1):
                        pos = i + j
                        if ans[pos] == '?':
                            ans[pos] = 'b'
                            changed = True
                            break
                    if not changed:
                        return ""

        # Fill remaining unknown characters with 'a'
        for i in range(L):
            if ans[i] == '?':
                ans[i] = 'a'

        return ''.join(ans)
