    A = data[1:1 + N]

    total_subarrays = N * (N + 1) // 2

    last = [0] * (N + 1)
    sum_last = 0
    distinct_total = 0

    for i, a in enumerate(A, 1):
        sum_last += i - last[a]
        last[a] = i
        distinct_total += sum_last

    pos = [[] for _ in range(N + 1)]
    for i, a in enumerate(A, 1):
        pos[a].append(i)

    no_occ = [total_subarrays] * (N + 1)

    for v in range(1, N + 1):
        p = pos[v]
        if not p:
            continue
        res = 0
        prev = 0
        for idx in p:
            gap = idx - prev - 1
            res += gap * (gap + 1) // 2
            prev = idx
        gap = N - prev
        res += gap * (gap + 1) // 2
        no_occ[v] = res

    pair_total = 0

    for x in range(1, N):
        P = pos[x]
        Q = pos[x + 1]
        if not P or not Q:
            continue

        i = j = 0
        prev = 0
        union_no = 0

        while i < len(P) or j < len(Q):
            if j >= len(Q) or (i < len(P) and P[i] < Q[j]):
                cur = P[i]
                i += 1
            else:
                cur = Q[j]
                j += 1

            gap = cur - prev - 1
            union_no += gap * (gap + 1) // 2
            prev = cur

        gap = N - prev
        union_no += gap * (gap + 1) // 2

        both = total_subarrays - no_occ[x] - no_occ[x + 1] + union_no
        pair_total += both

    answer = distinct_total - pair_total
    print(answer)

