            x = ord(ch) - 97
            for c in range(26):
                pref[c][i + 1] = pref[c][i] + abs(x - c)

        best = [array('i', [INF]) * 26 for _ in range(n + 1)]
        choice = [array('H', [0]) * 26 for _ in range(n + 1)]

        M = [INF] * 26
        less_min = [INF] * 26
        max_all = [-1] * 26

        for i in range(n, -1, -1):
            j = i + 3
            if j <= n:
                if j == n:
                    for c in range(26):
                        A = pref[c][j]
                        if A < M[c]:
                            M[c] = A
                            less_min[c] = INF
                            max_all[c] = j
                        elif A == M[c]:
                            if j > max_all[c]:
                                max_all[c] = j
                else:
                    bj = best[j]
                    min1 = INF
                    idx1 = -1
                    min2 = INF
                    idx2 = -1

                    for e in range(26):
                        val = bj[e]
                        if val < min1:
                            min2 = min1
                            idx2 = idx1
                            min1 = val
                            idx1 = e
                        elif val < min2:
                            min2 = val
                            idx2 = e

                    for c in range(26):
                        if c == idx1:
                            dp = min2
                            next_char = idx2
                        else:
                            dp = min1
                            next_char = idx1

                        if dp >= INF:
                            A = INF
                            cond = False
                        else:
                            A = pref[c][j] + dp
                            cond = (next_char != -1 and next_char < c)

                        mc = M[c]
                        if A < mc:
                            M[c] = A
                            less_min[c] = j if cond else INF
                            max_all[c] = j
                        elif A == mc:
                            if cond and j < less_min[c]:
                                less_min[c] = j
                            if j > max_all[c]:
                                max_all[c] = j

            if i < n:
                for c in range(26):
                    mc = M[c]
                    if mc < INF:
                        best[i][c] = mc - pref[c][i]
                        ch = less_min[c]
                        if ch == INF:
                            ch = max_all[c]
                        choice[i][c] = ch

        res = []
        i = 0
        prev = -1

        while i < n:
            b = best[i]

            if prev == -1:
                target = INF
                for e in range(26):
                    if b[e] < target:
                        target = b[e]
                if target >= INF:
                    return ""

                c = -1
                for e in range(26):
                    if b[e] == target:
                        c = e
                        break
            else:
                target = INF
                for e in range(26):
                    if e != prev and b[e] < target:
                        target = b[e]
                if target >= INF:
                    return ""

                c = -1
                for e in range(26):
                    if e != prev and b[e] == target:
                        c = e
                        break

            j = choice[i][c]
            if j <= i:
                return ""

            res.append(chr(c + 97) * (j - i))
            i = j
            prev = c

        return "".join(res)
