from array import array

class Solution:
    def minCostGoodCaption(self, caption: str) -> str:
        n = len(caption)
        if n < 3:
            return ""
        INF = 10**9

        # prefix sums of distances to each character
        pref = [array('i', [0]) * (n + 1) for _ in range(26)]
        for i, ch in enumerate(caption):
            x = ord(ch) - 97
            for c in range(26):
                pref[c][i + 1] = pref[c][i] + abs(x - c)

        dp = array('i', [0]) * ((n + 1) * 26)
        best_d = array('b', [-1]) * ((n + 1) * 26)
        best_j = array('i', [0]) * ((n + 1) * 26)
        best_d_none = array('b', [-1]) * (n + 1)

        min_g = [INF] * 26
        max_j = [-1] * 26
        min_less = [INF] * 26

        for i in range(n, -1, -1):
            j = i + 3
            if j <= n:
                for d in range(26):
                    val = pref[d][j] + dp[j * 26 + d]
                    if val < min_g[d]:
                        min_g[d] = val
                        max_j[d] = j
                        if j < n:
                            nd = best_d[j * 26 + d]
                            if nd != -1 and nd < d:
                                min_less[d] = j
                            else:
                                min_less[d] = INF
                        else:
                            min_less[d] = INF
                    elif val == min_g[d]:
                        if j > max_j[d]:
                            max_j[d] = j
                        if j < n:
                            nd = best_d[j * 26 + d]
                            if nd != -1 and nd < d:
                                if j < min_less[d]:
                                    min_less[d] = j

            if i < n:
                base = i * 26
                for d in range(26):
                    if min_less[d] != INF:
                        best_j[base + d] = min_less[d]
                    else:
                        best_j[base + d] = max_j[d] if max_j[d] != -1 else INF

                min1 = INF
                idx1 = -1
                min2 = INF
                idx2 = -1
                for d in range(26):
                    if min_g[d] >= INF:
                        val = INF
                    else:
                        val = min_g[d] - pref[d][i]
                    if val < min1:
                        min2 = min1
                        idx2 = idx1
                        min1 = val
                        idx1 = d
                    elif val < min2:
                        min2 = val
                        idx2 = d

                for c in range(26):
                    if c != idx1:
                        dp[base + c] = min1
                        best_d[base + c] = idx1
                    else:
                        dp[base + c] = min2
                        best_d[base + c] = idx2
                best_d_none[i] = idx1

        if best_d_none[0] == -1:
            return ""

        res = []
        i = 0
        prev = -1
        while i < n:
            if prev == -1:
                d = best_d_none[i]
            else:
                d = best_d[i * 26 + prev]
            if d == -1:
                return ""
            j = best_j[i * 26 + d]
            if j <= i:
                return ""
            res.append(chr(d + 97) * (j - i))
            i = j
            prev = d

        return "".join(res)
