from collections import deque

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    N = int(data[0])
    rows = data[1:1 + N]
    INF = 10 ** 9

    dist = [[INF] * N for _ in range(N)]
    visited = [0] * N
    q = deque()

    for i in range(N):
        dist[i][i] = 0
        visited[i] |= 1 << i
        q.append((i, i))

    out = [[0] * N for _ in range(26)]
    incoming = [[] for _ in range(N)]

    for u in range(N):
        row = rows[u]
        for v, ch in enumerate(row):
            if ch != '-':
                c = ord(ch) - ord('a')
                out[c][u] |= 1 << v
                incoming[v].append((u, c))

    for u in range(N):
        row = rows[u]
        for v, ch in enumerate(row):
            if ch != '-' and dist[u][v] == INF:
                dist[u][v] = 1
                visited[u] |= 1 << v
                q.append((u, v))

    while q:
        x, y = q.popleft()
        nd = dist[x][y] + 2

        for u, c in incoming[x]:
            mask = out[c][y]
            if mask == 0:
                continue

            new_bits = mask & ~visited[u]
            if new_bits:
                visited[u] |= new_bits

                while new_bits:
                    lsb = new_bits & -new_bits
                    v = lsb.bit_length() - 1
                    dist[u][v] = nd
                    q.append((u, v))
                    new_bits ^= lsb

    ans = []
    for i in range(N):
        row = []
        for j in range(N):
            if dist[i][j] == INF:
                row.append("-1")
            else:
                row.append(str(dist[i][j]))
        ans.append(" ".join(row))

    sys.stdout.write("\n".join(ans))

