from typing import List

class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)

        def can(x: int) -> bool:
            if x == 0:
                return True

            req = [(x + p - 1) // p for p in points]

            moves = 1
            visits = 1

            for i in range(n - 1):
                r = req[i]

                if visits < r:
                    d = r - visits
                    moves += 2 * d
                    if moves > m:
                        return False
                    carry = d
                else:
                    carry = 0

                if i == n - 2:
                    need = req[n - 1] - carry
                    if need > 0:
                        moves += 2 * need - 1
                        if moves > m:
                            return False
                else:
                    moves += 1
                    if moves > m:
                        return False
                    visits = carry + 1

            return moves <= m

        lo, hi = 0, max(points) * m + 1

        while lo < hi:
            mid = (lo + hi + 1) // 2
            if can(mid):
                lo = mid
            else:
                hi = mid - 1

        return lo
