import sys
from collections import deque

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    N = int(data[0])
    grid = data[1:1 + N]

    pred = [[0] * N for _ in range(26)]
    succ = [[0] * N for _ in range(26)]

    for i in range(N):
        row = grid[i]
        for j, ch in enumerate(row):
            if ch != '-':
                c = ord(ch) - ord('a')
                pred[c][j] |= 1 << i
                succ[c][i] |= 1 << j

    dist = [[-1] * N for _ in range(N)]
    unvisited = [(1 << N) - 1 for _ in range(N)]
    q = deque()

    for i in range(N):
        dist[i][i] = 0
        unvisited[i] &= ~(1 << i)
        q.append((i, i))

    for i in range(N):
        row = grid[i]
        for j, ch in enumerate(row):
            if ch != '-' and i != j:
                dist[i][j] = 1
                unvisited[i] &= ~(1 << j)
                q.append((i, j))

    while q:
        u, v = q.popleft()
        d = dist[u][v]
        nd = d + 2

        for c in range(26):
            pb = pred[c][u]
            if pb == 0:
                continue
            sb = succ[c][v]
            if sb == 0:
                continue

            bits = pb
            while bits:
                lsb = bits & -bits
                s = lsb.bit_length() - 1
                bits ^= lsb

                targets = sb & unvisited[s]
                if targets:
                    unvisited[s] &= ~targets

                    tb = targets
                    while tb:
                        lsb2 = tb & -tb
                        t = lsb2.bit_length() - 1
                        tb ^= lsb2
                        dist[s][t] = nd
                        q.append((s, t))

    out = []
    for i in range(N):
        out.append(' '.join(map(str, dist[i])))
    sys.stdout.write('\n'.join(out))

if __name__ == "__main__":
    main()
