class Solution:
    def maxFrequency(self, nums: List[int], k: int) -> int:
        total_k = nums.count(k)
        max_gain = 0

        for v in range(1, 51):
            if v == k:
                continue

            cur = 0
            best = 0

            for num in nums:
                if num == v:
                    cur += 1
                elif num == k:
                    cur -= 1

                if cur < 0:
                    cur = 0
                if cur > best:
                    best = cur

            if best > max_gain:
                max_gain = best

        return total_k + max_gain
