import sys

MOD = 998244353

def solve():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    it = iter(data)
    T = int(next(it))
    out = []
    for _ in range(T):
        H = int(next(it))
        W = int(next(it))
        V = 2 * H * W
        parent = list(range(V))
        rank = [0] * V
        diff = [0] * V

        def find(x):
            root = x
            parity = 0
            while parent[root] != root:
                parity ^= diff[root]
                root = parent[root]
            cur = x
            cur_parity = 0
            while parent[cur] != cur:
                nxt = parent[cur]
                d = diff[cur]
                parent[cur] = root
                diff[cur] = parity ^ cur_parity
                cur_parity ^= d
                cur = nxt
            return root, parity

        def union(x, y, c):
            rx, px = find(x)
            ry, py = find(y)
            if rx == ry:
                return (px ^ py) == c
            val = c ^ px ^ py
            if rank[rx] < rank[ry]:
                parent[rx] = ry
                diff[rx] = val
            else:
                parent[ry] = rx
                diff[ry] = val
                if rank[rx] == rank[ry]:
                    rank[rx] += 1
            return True

        ok = True
        for i in range(H):
            row = next(it).decode()
            base_h = i * W
            base_v = H * W + i * W
            for j in range(W):
                left = base_h + (j - 1) % W
                right = base_h + j
                top = H * W + ((i - 1) % H) * W + j
                bottom = base_v + j
                ch = row[j]
                if ch == 'A':
                    if not union(left, right, 1):
                        ok = False
                        break
                    if not union(top, bottom, 1):
                        ok = False
                        break
                else:
                    if not union(left, right, 0):
                        ok = False
                        break
                    if not union(top, bottom, 0):
                        ok = False
                        break
                    if not union(left, top, 1):
                        ok = False
                        break
            if not ok:
                break

        if not ok:
            out.append("0")
        else:
            comp = 0
            for i in range(V):
                if parent[i] == i:
                    comp += 1
            ans = pow(2, comp, MOD)
            out.append(str(ans))

    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    solve()
