from typing import List

class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        S = side
        L = 4 * S
        t = []
        for x, y in points:
            if y == 0:
                t.append(x)
            elif x == S:
                t.append(S + y)
            elif y == S:
                t.append(2 * S + (S - x))
            else:
                t.append(3 * S + (S - y))
        t.sort()
        n = len(t)

        def can(d: int) -> bool:
            if d == 0:
                return n >= k
            arr = t + [v + L for v in t]
            m = 2 * n
            nxt = [0] * m
            j = 0
            for i in range(m):
                if j <= i:
                    j = i + 1
                target = arr[i] + d
                while j < m and arr[j] < target:
                    j += 1
                nxt[i] = j

            for i in range(n):
                limit = arr[i] + L - d
                last = i
                cnt = 1
                while cnt < k:
                    nxt_idx = nxt[last]
                    if nxt_idx >= i + n:
                        break
                    if arr[nxt_idx] > limit:
                        break
                    last = nxt_idx
                    cnt += 1
                if cnt >= k:
                    return True
            return False

        lo, hi = 0, S
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if can(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo
