class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)
        N = n + m - 1
        pat = [ord(c) - 97 for c in str2]
        forced = [-1] * N

        for i, ch in enumerate(str1):
            if ch == 'T':
                for k in range(m):
                    pos = i + k
                    c = pat[k]
                    if forced[pos] == -1:
                        forced[pos] = c
                    elif forced[pos] != c:
                        return ""

        pi = [0] * m
        for i in range(1, m):
            j = pi[i-1]
            while j > 0 and pat[i] != pat[j]:
                j = pi[j-1]
            if pat[i] == pat[j]:
                j += 1
            pi[i] = j

        trans = [[0] * 26 for _ in range(m)]
        for q in range(m):
            for c in range(26):
                if c == pat[q]:
                    if q == m - 1:
                        trans[q][c] = pi[q]
                    else:
                        trans[q][c] = q + 1
                else:
                    if q == 0:
                        trans[q][c] = 0
                    else:
                        trans[q][c] = trans[pi[q-1]][c]

        out_any = [0] * m
        for q in range(m):
            mask = 0
            for c in range(26):
                mask |= 1 << trans[q][c]
            out_any[q] = mask

        last_char = pat[m-1]
        out_except_last = 0
        q_last = m - 1
        for c in range(26):
            if c != last_char:
                out_except_last |= 1 << trans[q_last][c]

        forbidden = [False] * N
        for j in range(N):
            if j >= m - 1:
                start = j - m + 1
                if start < n and str1[start] == 'F':
                    forbidden[j] = True

        all_mask = (1 << m) - 1
        dp = [0] * (N + 1)
        dp[N] = all_mask

        for j in range(N - 1, -1, -1):
            next_mask = dp[j+1]
            if forced[j] != -1:
                c = forced[j]
                prev = 0
                forbid_match = forbidden[j] and (c == last_char)
                for qstate in range(m):
                    if forbid_match and qstate == m - 1:
                        continue
                    nq = trans[qstate][c]
                    if (next_mask >> nq) & 1:
                        prev |= 1 << qstate
                dp[j] = prev
            else:
                prev = 0
                if forbidden[j]:
                    if out_except_last & next_mask:
                        prev |= 1 << (m - 1)
                    for qstate in range(m - 1):
                        if out_any[qstate] & next_mask:
                            prev |= 1 << qstate
                else:
                    for qstate in range(m):
                        if out_any[qstate] & next_mask:
                            prev |= 1 << qstate
                dp[j] = prev

        if not (dp[0] >> 0) & 1:
            return ""

        res = []
        q = 0
        for j in range(N):
            next_mask = dp[j+1]
            if forced[j] != -1:
                candidates = [forced[j]]
            else:
                candidates = range(26)
            chosen = -1
            for c in candidates:
                if forbidden[j] and q == m - 1 and c == last_char:
                    continue
                nq = trans[q][c]
                if (next_mask >> nq) & 1:
                    chosen = c
                    break
            if chosen == -1:
                return ""
            res.append(chr(chosen + 97))
            q = trans[q][chosen]
        return ''.join(res)
