from typing import List
from array import array

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n = len(grid)
        m = len(grid[0])
        size = n * m
        dirs = [(1, 1), (1, -1), (-1, -1), (-1, 1)]

        # F1[d][k][idx]: already turned, direction d, expected value is 2 if k=0 else 0
        F1 = [[array('H', [0]) * size for _ in range(2)] for _ in range(4)]

        for d in range(4):
            dx, dy = dirs[d]
            arr0 = F1[d][0]  # expected 2
            arr1 = F1[d][1]  # expected 0

            if d == 0:
                irange = range(n - 1, -1, -1)
                jrange = range(m - 1, -1, -1)
            elif d == 1:
                irange = range(n - 1, -1, -1)
                jrange = range(0, m)
            elif d == 2:
                irange = range(0, n)
                jrange = range(0, m)
            else:
                irange = range(0, n)
                jrange = range(m - 1, -1, -1)

            for i in irange:
                ni = i + dx
                base = i * m
                for j in jrange:
                    idx = base + j
                    val = grid[i][j]
                    nj = j + dy

                    if 0 <= ni < n and 0 <= nj < m:
                        nidx = ni * m + nj
                        if val == 2:
                            arr0[idx] = 1 + arr1[nidx]
                        else:
                            arr0[idx] = 0
                        if val == 0:
                            arr1[idx] = 1 + arr0[nidx]
                        else:
                            arr1[idx] = 0
                    else:
                        if val == 2:
                            arr0[idx] = 1
                        else:
                            arr0[idx] = 0
                        if val == 0:
                            arr1[idx] = 1
                        else:
                            arr1[idx] = 0

        # F0[d][k][idx]: not turned yet, direction d, expected value is 2 if k=0 else 0
        F0 = [[array('H', [0]) * size for _ in range(2)] for _ in range(4)]

        for d in range(4):
            dx, dy = dirs[d]
            cw = (d + 1) % 4
            cdx, cdy = dirs[cw]

            arr0 = F0[d][0]  # expected 2
            arr1 = F0[d][1]  # expected 0

            cont0_arr = F0[d][1]
            cont1_arr = F0[d][0]
            turn0_arr = F1[cw][1]
            turn1_arr = F1[cw][0]

            if d == 0:
                irange = range(n - 1, -1, -1)
                jrange = range(m - 1, -1, -1)
            elif d == 1:
                irange = range(n - 1, -1, -1)
                jrange = range(0, m)
            elif d == 2:
                irange = range(0, n)
                jrange = range(0, m)
            else:
                irange = range(0, n)
                jrange = range(m - 1, -1, -1)

            for i in irange:
                base = i * m
                ni = i + dx
                ti = i + cdx
                for j in jrange:
                    idx = base + j
                    val = grid[i][j]
                    nj = j + dy

                    if 0 <= ni < n and 0 <= nj < m:
                        nidx = ni * m + nj
                        cont0 = cont0_arr[nidx]
                        cont1 = cont1_arr[nidx]
                    else:
                        cont0 = 0
                        cont1 = 0

                    tj = j + cdy
                    if 0 <= ti < n and 0 <= tj < m:
                        tidx = ti * m + tj
                        turn0 = turn0_arr[tidx]
                        turn1 = turn1_arr[tidx]
                    else:
                        turn0 = 0
                        turn1 = 0

                    if val == 2:
                        m0 = cont0 if cont0 >= turn0 else turn0
                        arr0[idx] = 1 + m0
                    else:
                        arr0[idx] = 0

                    if val == 0:
                        m1 = cont1 if cont1 >= turn1 else turn1
                        arr1[idx] = 1 + m1
                    else:
                        arr1[idx] = 0

        ans = 0
        for i in range(n):
            base = i * m
            for j in range(m):
                if grid[i][j] == 1:
                    best = 1
                    for d in range(4):
                        dx, dy = dirs[d]
                        ni = i + dx
                        nj = j + dy
                        if 0 <= ni < n and 0 <= nj < m:
                            cand = 1 + F0[d][0][ni * m + nj]
                            if cand > best:
                                best = cand
                    if best > ans:
                        ans = best

        return ans
