class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)
        L = n + m - 1
        ans = ['?'] * L
        is_free = [True] * L

        # Process all 'T' constraints
        for i in range(n):
            if str1[i] == 'T':
                for j in range(m):
                    pos = i + j
                    if ans[pos] != '?' and ans[pos] != str2[j]:
                        return ""
                    ans[pos] = str2[j]
                    is_free[pos] = False

        # Fill unconstrained positions with 'a'
        for i in range(L):
            if ans[i] == '?':
                ans[i] = 'a'

        last_selected = -1

        # Process 'F' windows in order
        for i in range(n):
            if str1[i] == 'F':
                # Check if the current window already equals str2
                match = True
                for j in range(m):
                    if ans[i + j] != str2[j]:
                        match = False
                        break

                if match:
                    if last_selected < i:
                        # Need to break this window by changing a free position
                        found = -1
                        for pos in range(i + m - 1, i - 1, -1):
                            if is_free[pos]:
                                found = pos
                                break
                        if found == -1:
                            return ""
                        ans[found] = 'b'
                        last_selected = found

        return ''.join(ans)
